window.ScripturaLexicons.BDAG_PART_0121 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-endyo-bdag\" data-source=\"BDAG\" data-search=\"ἐνδύω endýō verbo; ativo e médio vestir; revestir; vestir-se; assumir qualidades BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνδύω</td><td>verbo; ativo e médio</td><td>vestir; revestir; vestir-se; assumir qualidades</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-endomesis-omega-bdag\" data-source=\"BDAG\" data-search=\"ἐνδώμησις, εως, ἡ endṓmēsis substantivo feminino estrutura interior; construção; material de construção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνδώμησις, εως, ἡ</td><td>substantivo feminino</td><td>estrutura interior; construção; material de construção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enegk-bdag\" data-source=\"BDAG\" data-search=\"ἐνεγκ- enegk- forma remissiva ver φέρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνεγκ-</td><td>forma remissiva</td><td>ver φέρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enedra-bdag\" data-source=\"BDAG\" data-search=\"ἐνέδρα, ας, ἡ enédra substantivo feminino emboscada; cilada; ardil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέδρα, ας, ἡ</td><td>substantivo feminino</td><td>emboscada; cilada; ardil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enedreuo-bdag\" data-source=\"BDAG\" data-search=\"ἐνεδρεύω enedreúō verbo armar emboscada; espreitar; conspirar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνεδρεύω</td><td>verbo</td><td>armar emboscada; espreitar; conspirar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enedron-bdag\" data-source=\"BDAG\" data-search=\"ἔνεδρον, ου, τό énedron substantivo neutro emboscada; ardil; ver ἐνέδρα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνεδρον, ου, τό</td><td>substantivo neutro</td><td>emboscada; ardil; ver ἐνέδρα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eneileo-bdag\" data-source=\"BDAG\" data-search=\"ἐνειλέω eneiléō verbo envolver; enfaixar; confinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνειλέω</td><td>verbo</td><td>envolver; enfaixar; confinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eneimi-bdag\" data-source=\"BDAG\" data-search=\"ἔνειμι éneimi verbo; emprego impessoal estar dentro; conter; ser possível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔνειμι</td><td>verbo; emprego impessoal</td><td>estar dentro; conter; ser possível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heneka-bdag\" data-source=\"BDAG\" data-search=\"ἕνεκα héneka preposição com genitivo por causa de; em razão de; por amor de; a fim de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕνεκα</td><td>preposição com genitivo</td><td>por causa de; em razão de; por amor de; a fim de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enekrypsa-bdag\" data-source=\"BDAG\" data-search=\"ἐνέκρυψα enékrypsa forma verbal remissiva ver ἐγκρύπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέκρυψα</td><td>forma verbal remissiva</td><td>ver ἐγκρύπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enelisso-bdag\" data-source=\"BDAG\" data-search=\"ἐνελίσσω enelíssō verbo; forma conjectural envolver; enrolar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνελίσσω</td><td>verbo; forma conjectural</td><td>envolver; enrolar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enemeina-bdag\" data-source=\"BDAG\" data-search=\"ἐνέμεινα enémeina forma verbal remissiva ver ἐμμένω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέμεινα</td><td>forma verbal remissiva</td><td>ver ἐμμένω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enenekonta-bdag\" data-source=\"BDAG\" data-search=\"ἐνενήκοντα enenḗkonta numeral indeclinável noventa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνενήκοντα</td><td>numeral indeclinável</td><td>noventa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eneos-bdag\" data-source=\"BDAG\" data-search=\"ἐνεός, ά, όν eneós adjetivo mudo; sem fala; sem palavras; estupefato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνεός, ά, όν</td><td>adjetivo</td><td>mudo; sem fala; sem palavras; estupefato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enepaixa-enepaichthen-bdag\" data-source=\"BDAG\" data-search=\"ἐνέπαιξα, ἐνεπαίχθην enépaixa, enepaíchthēn formas verbais remissivas ver ἐμπαίζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέπαιξα, ἐνεπαίχθην</td><td>formas verbais remissivas</td><td>ver ἐμπαίζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-enepeson-bdag\" data-source=\"BDAG\" data-search=\"ἐνέπεσον enepéson forma verbal remissiva ver ἐμπίπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέπεσον</td><td>forma verbal remissiva</td><td>ver ἐμπίπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eneplesa-eneplesthen-bdag\" data-source=\"BDAG\" data-search=\"ἐνέπλησα, ἐνεπλήσθην enéplēsa, eneplḗsthēn formas verbais remissivas ver ἐμπίμπλημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέπλησα, ἐνεπλήσθην</td><td>formas verbais remissivas</td><td>ver ἐμπίμπλημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eneprese-bdag\" data-source=\"BDAG\" data-search=\"ἐνέπρησε enéprēse forma verbal remissiva ver ἐμπίμπρημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέπρησε</td><td>forma verbal remissiva</td><td>ver ἐμπίμπρημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-energeia-bdag\" data-source=\"BDAG\" data-search=\"ἐνέργεια, ας, ἡ enérgeia substantivo feminino atividade; operação; ação; eficácia; atuação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνέργεια, ας, ἡ</td><td>substantivo feminino</td><td>atividade; operação; ação; eficácia; atuação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-energeo-bdag\" data-source=\"BDAG\" data-search=\"ἐνεργέω energéō verbo; transitivo e intransitivo atuar; operar; ser eficaz; realizar; produzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐνεργέω</td><td>verbo; transitivo e intransitivo</td><td>atuar; operar; ser eficaz; realizar; produzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-endyo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνδύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦endýō⟧</span><span class=\"separator\">·</span><span>verbo; ativo e médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro ativo <span class=\"greek\">ἐνδύσω</span> (LXX); primeiro aoristo ativo <span class=\"greek\">ἐνέδυσα</span>; particípio perfeito ativo <span class=\"greek\">ἐνδεδυκώς</span> (LXX); infinitivo mais-que-perfeito <span class=\"greek\">ἐνδεδύκειν</span> (LXX). Voz média: futuro <span class=\"greek\">ἐνδύσομαι</span> (LXX); primeiro aoristo <span class=\"greek\">ἐνεδυσάμην</span>; particípio perfeito <span class=\"greek\">ἐνδεδυμένος</span>. De <span class=\"greek\">δύω</span>, «entrar em, vestir» (Homero e outros; papiros, LXX; PsSol 11:7; TestJob; Test12Patr; JosAs; ApcMos 20; Fílon; Josefo; Justino, A I, 52, 3 [cf. as citações na acepção 2a]).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Na voz ativa, pôr roupa ou vestimenta em alguém: vestir, revestir.</strong> Com acusativo <span class=\"greek\">τινά</span>, «alguém» (Apiano, Bell. Civ. 5, 99 §411; PGiss 77, 8; Gn 3:21; Êx 29:5; Nm 20:26), <span class=\"greek\">ἐνδύσατε</span> <span class=\"greek\">αὐτόν</span>, «vesti-o», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:22</a>. Com duplo acusativo <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span>, «vestir alguém com alguma coisa» (autores clássicos; Diodoro Sículo 2, 27, 3; Gn 41:42; Êx 40:13; 1Mc 10:62 e outros; Justino, A I, 52, 3; Mel., P. 17, 116): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:28</a>, variante textual; 27:31; <span class=\"greek\">ἐνέδυσαν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτοῦ</span>, «vestiram-no com as suas roupas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:20</a>; <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔνδυμα</span> <span class=\"greek\">αὐτῶν</span>, «vesti-lo com a roupa delas», Hs 9, 13, 2 (ver <span class=\"greek\">ἐνδιδύσκω</span>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Na voz média, pôr sobre si qualquer espécie de coisa: vestir-se de, pôr, usar</strong>, com acusativo <span class=\"greek\">τί</span>, «alguma coisa».</p>\n<p class=\"entry-text\">ⓐ <strong>Literalmente</strong> (PsSol 11:7; TestJob 39:5; Fílon, Somn. 1, 214): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:22</a>; Ox 655, 6s. (ASyn. 67, 33; cf. GTh 36); <span class=\"greek\">ἱμάτιον</span>, «uma veste», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:27</a>; cf. Hs 9, 13, 8; 9, 15, 1; GJs 2:4; <span class=\"greek\">ἱματισμόν</span>, «vestuário», Hs 9, 13, 3; <span class=\"greek\">δύο</span> <span class=\"greek\">χιτῶνας</span>, «duas túnicas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:9</a>; <span class=\"greek\">ἐσθῆτα</span> <span class=\"greek\">βασιλικήν</span>, «veste real», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:21</a>; <span class=\"greek\">σάκκον</span>, «saco», B 3:2 (cf. Sl 34:13; Jn 3:5; Josefo, Ant. 8, 385; 11, 256); <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπλα</span>, «as armas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:12</a>; <span class=\"greek\">τὴν</span> <span class=\"greek\">πανοπλίαν</span>, «vestir toda a armadura» (Josefo, Ant. 13, 309), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:11</a>; cf. v. 14; <span class=\"greek\">θώρακα</span> <span class=\"greek\">πίστεως</span>, «couraça da fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:8</a> (cf. Wsd 5:18 [especialmente a leitura de S]; Is 59:17; TestLevi 8:2: <span class=\"greek\">ἔνδυσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέταλον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>; Josefo, Ant. 7, 283: <span class=\"greek\">θώρακα</span> <span class=\"greek\">ἐνδεδυμένος</span>; sobre o assunto, ver M. Dibelius, Hdb., sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:11</a>; cf. Reader, Polemo, p. 366).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐνδεδυμένος</span>, «vestido» (POxy 285, 11 [cerca de 50 d.C.]: <span class=\"greek\">ἐνδεδυμένος</span> <span class=\"greek\">χιτῶνα</span> <span class=\"greek\">λεινοῦν</span>; 2Cr 5:12; Dn 10:5); com <span class=\"greek\">ἔνδυμα</span>, «com uma veste» (Sf 1:8), AcPt 5:17; Ox 840, 27s.; <span class=\"greek\">ἔνδυμα</span> <span class=\"greek\">γάμου</span>, «veste nupcial», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:11</a>; <span class=\"greek\">τρίχας</span> <span class=\"greek\">καμήλου</span>, «pelos de camelo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:6</a>; <span class=\"greek\">χιτῶνας</span>, «túnicas», Hs 9, 2, 4; <span class=\"greek\">βύσσινον</span>, «veste de linho fino», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19:14</a>; <span class=\"greek\">ποδήρη</span>, «veste comprida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:13</a>; <span class=\"greek\">λίνον</span> <span class=\"greek\">καθαρόν</span>, «linho limpo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 15:6</a>; <span class=\"greek\">σύνθεσιν</span> <span class=\"greek\">ἱματίων</span>, «conjunto de roupas», Hs 6, 1, 5; <span class=\"greek\">μέλανα</span>, «vestes negras», 9, 9, 5; <span class=\"greek\">ῥάκη</span> <span class=\"greek\">ῥυπαρά</span>, «trapos sujos», ApcPt 15:30 (<span class=\"greek\">δέρματα</span> <span class=\"greek\">προβάτων</span>, «peles de ovelhas», Justino, A I, 16, 13 e D. 35, 3 [para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐνδύμασι</span>]). — Emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:3</a>, variante textual (em lugar de <span class=\"greek\">ἐκδυσάμενοι</span>); aqui é incerto se se deve suprir um objeto ou se caberia traduzir «quando estivermos vestidos» (cf. Aristóteles, Anima 1, 3, 407b, 23: <span class=\"greek\">ψυχὴν</span> … <span class=\"greek\">ἐνδύεσθαι</span> <span class=\"greek\">σῶμα</span>; Herm. Wr. 10, 18). ApcPt 6:21. Sobre o assunto, ver a bibliografia em <span class=\"greek\">γυμνός</span> 1b.</p>\n<p class=\"entry-text\">ⓑ <strong>Metaforicamente</strong>, muito frequentemente, de assumir características, virtudes, intenções etc. (LXX; PGM 11a, 19: <span class=\"greek\">πάλιν</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐνδύσεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑαυτῆς</span> <span class=\"greek\">κάλλος</span> <span class=\"greek\">ὅπερ</span> <span class=\"greek\">ἐξεδύσατο</span>; Irineu 1, 9, 3 [Harv. I 85, 1]: <span class=\"greek\">τὸν</span> <span class=\"greek\">σωτῆρα</span> <span class=\"greek\">ἐνδύσασθαι</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ψυχικόν</span> [ensinamento herético]). Especialmente na linguagem de Hermas, sobre a qual provavelmente influiu o emprego latino de <em>induere</em> no mesmo sentido (exemplos em Wetstein, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:49</a>). O sentido médio nem sempre é claramente o correto; às vezes a interpretação passiva é melhor.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀφθαρσίαν</span>, «incorruptibilidade», 1Co 15:53s. (citado em Atenágoras, R. 71, 16); <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὕψους</span> <span class=\"greek\">δύναμιν</span>, «ser revestido de poder do alto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:49</a>; cf. Hs 9, 13, 8 (cf. Sl 92:1); <span class=\"greek\">δόξαν</span>, «glória», ApcPt 3, 7; <span class=\"greek\">ἰσχύν</span>, «força» (Is 51:9; 52:1; Pv 31:26), Hv 3, 12, 2; <span class=\"greek\">σπλάγχνα</span> <span class=\"greek\">οἰκτιρμοῦ</span>, «compaixão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:12</a>; <span class=\"greek\">ἀκακίαν</span>, «inocência», Hs 9, 29, 3; <span class=\"greek\">ἀλήθειαν</span>, «verdade», m 11:4; <span class=\"greek\">ἀρετήν</span>, «virtude», m 1:2; Hs 6, 1, 4; <span class=\"greek\">ἀφροσύνην</span>, «insensatez», 6, 5, 3; <span class=\"greek\">ἐπιθυμίαν</span>, «desejo», m 12, 1, 1; 12, 2, 4; <span class=\"greek\">ἱλαρότητα</span>, «alegria», 10, 3, 1 e 4; <span class=\"greek\">μακροθυμίαν</span>, «longanimidade», 5, 2, 8; <span class=\"greek\">πίστιν</span>, «fé» (Fílon, Conf. Lingu. 31), v 4, 1, 8; m 9:7; Hs 6, 1, 2; <span class=\"greek\">σεμνότητα</span>, «dignidade», m 2:4; <span class=\"greek\">ὑπερηφανίαν</span>, «arrogância», Hs 8, 9, 1; <span class=\"greek\">ὁμόνοιαν</span>, «concórdia», 1Cl 30:3; <span class=\"greek\">χάριν</span>, «graça», IPol 1:2.</p>\n<p class=\"entry-text\">Observe-se a figura expressiva <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">ἐ</span>., «revestir-se do Senhor Jesus Cristo» (cf. Dionísio de Halicarnasso 11, 5: <span class=\"greek\">Ταρκύνιον</span> <span class=\"greek\">ἐνδύεσθαι</span>; Éfipo [posterior a 323 a.C.; 126 Fgm. 5 Jac., em Ateneu 12, 53, 537e]: Alexandre, o Grande, apreciava vestir as <span class=\"greek\">ἱερὰς</span> <span class=\"greek\">ἐσθῆτας</span>, «vestes sagradas», dos deuses, tornando-se assim Amon, Ártemis, Hermes ou Héracles; Artemidoro 3, 14: <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σκευὴν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περικεῖσθαι</span>; sobre a encarnação, Mel., P. 66, 468; 100, 767), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:27</a> (ver Apuleio, Metamorph. 11; também M. Dibelius, Die Isisweihe etc., Botschaft u. Geschichte 2, 1956, pp. 30–79). Semelhantemente, Hs 9, 24, 2 diz <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">ἐ</span>., «revestir-se do Espírito Santo», expressando a mesma ideia que <span class=\"greek\">τὸν</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">ἄνθρωπον</span>, «revestir-se da nova pessoa (isto é, espiritual)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:10</a>. Para a figura, ver F. Dölger, <span class=\"greek\">ΙΧΘΥΣ</span> I, 1910, pp. 116ss.; W. Straub, D. Bildersprache des Ap. Pls, 1937, pp. 24s., 84s. — B. 393; DELG, s.v. <span class=\"greek\">δύω</span>; M-M.; TW.</p></section></article>\n<article id=\"entry-endomesis-omega-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνδώμησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦endṓmēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">De <span class=\"greek\">δωμάω</span>, «construir»; a grafia com -<span class=\"greek\">δό</span>- ocorre como variante textual em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:18</a>; empregada para uma construção destinada a fins cultuais em SIG 996, 31 (século I d.C.?); também encontrada numa inscrição de Trales: BCH 28, 1904, p. 78, linha 9. Josefo, Ant. 15, 335 apresenta <span class=\"greek\">ἐνδόμησις</span> na maioria dos manuscritos (um deles lê <span class=\"greek\">ἐνδώμησις</span>) com o sentido de «molhe num porto». Significado primário: <strong>estrutura interior</strong>; em nossa literatura, provavelmente equivale a <strong>construção</strong> e, consequentemente, <strong>material</strong>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">τείχους</span>, «da muralha», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21:18</a>. — DELG, s.v. <span class=\"greek\">δέμω</span>; M-M., s.v. -<span class=\"greek\">δομ</span>-.</p></section></article>\n<article id=\"entry-enegk-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνεγκ-</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enegk-⟧</span><span class=\"separator\">·</span><span>forma remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">φέρω</span></strong>.</p></section></article>\n<article id=\"entry-enedra-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέδρα, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enédra⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver verbete seguinte; Tucídides e outros; Fílon, Spec. Leg. 4, 67; Josefo, Vi. 216 e outros; papiros, LXX; JosAs 8:5; 26:5. Significado primário: «estar sentado dentro»; daí, como ato de ocultação com vistas a um ataque de surpresa: <strong>emboscada</strong>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ποιεῖν</span> (Tucídides 3, 90, 2: <span class=\"greek\">ἐνέδραν</span> <span class=\"greek\">πεποιημένοι</span>; Paléfato 1, p. 4, 16; 4, p. 11, 18), «preparar uma emboscada», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:16</a> (variante textual <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔνεδρον</span>). <strong>Ciladas, armadilhas</strong>: <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβόλου</span>, «as ciladas do diabo», ITr 8:1; cf. IPhld 6:2. — B. 1417; DELG, s.v. <span class=\"greek\">ἕζομαι</span> B2, p. 314; M-M.</p></section></article>\n<article id=\"entry-enedreuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνεδρεύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enedreúō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver verbete anterior; futuro, terceira pessoa do singular, <span class=\"greek\">ἐνεδρεύσει</span>, Sir 27:28; primeiro aoristo <span class=\"greek\">ἐνήδρευσα</span>, LXX. De <span class=\"greek\">ἔνεδρα</span>, «estar sentado dentro» (Tucídides e outros; inscrições, papiros, LXX; JosAs).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Ocultar-se em posição adequada para um ataque de surpresa: ficar de emboscada, espreitar</strong>, com acusativo <span class=\"greek\">τινά</span>, «alguém» (Ps.-Demóstenes 40, 10; Diodoro Sículo 19, 69, 1; SIG 730, 19 [século I a.C.]; PRein 7, 26 [século II a.C.]; Dt 19:11; Wsd 2:12; Josefo, Bell. 2, 595; Ant. 5, 172), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:21</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Valer-se de intriga: tramar, conspirar</strong>, com infinitivo subsequente (cf. Josefo, Ant. 6, 331), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:54</a>. — M-M.</p></section></article>\n<article id=\"entry-enedron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνεδρον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦énedron⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Herodiano, Gramm. I, 378, 2; equivale a «engano» em POxy 892, 11 [338 d.C.]. Na LXX, quase suplantou a forma mais antiga <span class=\"greek\">ἐνέδρα</span> (ver Thackeray, pp. 156s.). <strong>Equivale a <span class=\"greek\">ἐνέδρα</span></strong> (ver esse verbete), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:16</a>, variante textual. — M-M.</p></section></article>\n<article id=\"entry-eneileo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνειλέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eneiléō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνείλησα</span> (Ps.-Aristóteles, De Mundo 4, 396a, 14; Artemidoro 1, 54 e outros; PTebt 24, 62 [117 a.C.]; PRyl 144, 19s. [38 d.C.]; 1 Km 21:10; TestJud 3:6).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Envolver um objeto, enrolando-o em alguma coisa: envolver, enfaixar</strong>, com dativo <span class=\"greek\">τινί</span>, «em algo» (Eneias Tático 1346; Plutarco, Brut. 1005 [45, 4]; Dio Crisóstomo 73 [23], 3: <span class=\"greek\">σπαργάνοις</span>, «em faixas»; Filóstrato, Her. 12, 1, p. 187, 2: <span class=\"greek\">βρέφος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">λεοντῇ</span>, «a criança na pele de leão»). <span class=\"greek\">τῇ</span> <span class=\"greek\">σινδόνι</span>, «no pano de linho» (Dioscórides 5, 72: <span class=\"greek\">τί</span> <span class=\"greek\">ὀθονίῳ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:46</a>; GPt 6:24 (assim Gebhardt e Blass; ver <span class=\"greek\">εἰλέω</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Cercar um objeto com material que o mantém preso: confinar em</strong>, com dativo do meio de confinamento, extensão da acepção 1: <span class=\"greek\">ἐνειλημένος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεσμοῖς</span>, «preso em correntes», Pol 1:1 (variante -<span class=\"greek\">λημμ</span>- no códice Vaticano; ver <span class=\"greek\">ἐνελίσσω</span>). — DELG, s.v. 1 <span class=\"greek\">εἰλέω</span>; M-M.</p></section></article>\n<article id=\"entry-eneimi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔνειμι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éneimi⟧</span><span class=\"separator\">·</span><span>verbo; emprego impessoal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Particípio <span class=\"greek\">ἐνών</span>; imperfeito, terceira pessoa do plural, <span class=\"greek\">ἐνῆσαν</span>, 3Rs 10:17 (ver <span class=\"greek\">εἰμί</span> 1, no sentido de «ser, existir»; Homero e outros; papiros, LXX; TestSol 13:3 P; EpArist 285; Josefo).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Estar dentro de uma área ou objeto: estar em, encontrar-se dentro</strong>, 2Cl 19:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνόντα</span>, «aquilo que está dentro, o conteúdo» (Tucídides 4, 57, 3 e outros; PTebt 414, 20 [século II d.C.]: <span class=\"greek\">τὸ</span> <span class=\"greek\">σφυρίδιν</span> [=-<span class=\"greek\">ιον</span>] <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐνόντων</span>; Josefo, Bell. 6, 183; Justino, A II, 13, 5; Atenágoras, R. 75, 24 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:41</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Estar dentro dos limites da realização: ser possível</strong>; impessoal <span class=\"greek\">ἔνεστι</span> (Políbio 21, 4, 14; 22, 14, 2; 4Mc 4:22; Fílon, Migr. Abr. 189: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔνι</span> <span class=\"greek\">μάλιστα</span>, «tanto quanto possível»; Fálaris, Ep. 88: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐνῆν</span>; Josefo, Ant. 1, 244; Justino, D. 46, 2; Taciano 19, 2; Atenágoras 31, 2), IRo 4:1; Hs 8, 10, 2, variante textual. Forma abreviada <span class=\"greek\">ἔνι</span>, ver verbete. — M-M.</p></section></article>\n<article id=\"entry-heneka-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕνεκα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦héneka⟧</span><span class=\"separator\">·</span><span>preposição com genitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Forma ática <span class=\"greek\">ἕνεκα</span> (PLond I, 42, 14, p. 30 [172 a.C.]; POxy 533, 25; 1293, 16s. [outros exemplos em Mayser, p. 242]; LXX [Thackeray, p. 135]; OdeSol 11:17; Josefo, Ant. 3, 107). Essa forma ocorre em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:32</a>, mas é atestada unanimemente somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:21</a>. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:10</a>; 19:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:36</a> (todos apenas em certos manuscritos); 2Cl 1:2; MPol 17:3; Hv 1, 3, 1; m 12, 4, 2.</p>\n<p class=\"entry-text\">Variante <strong><span class=\"greek\">ἕνεκεν</span></strong>, progressivamente mais importante desde o século III a.C.: é a forma predominante em inscrições (Meisterhans³-Schw., p. 217; Threatte II, pp. 666–668; Thieme, p. 8; Hauser, p. 21), em papiros (Mayser, p. 241), na LXX (Thackeray, p. 82), em TestAbr A 17, p. 99, 10 [Stone, p. 46], EpArist, Ar. [Milne, p. 74, 24], Taciano, Atenágoras (R.) e nossa literatura. Justino usa essa forma, mas apenas em citações. Variante <strong><span class=\"greek\">εἵνεκεν</span></strong>, ver verbete (Sb 1568, 7 [século II a.C.]; PGiss 40 II, 21; PGM 5, 385; inscrições desde 161 d.C. [Meisterhans³-Schw., p. 216]; LXX [Thackeray, pp. 82s.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a> [Is 61:1]; 18:29, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:20</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:10</a>; 7:12, variante textual; Hv 3, 2, 1). Variante <strong><span class=\"greek\">εἵνεκα</span></strong> (O. Wilck II 1148 [século II a.C.]; En 101:2; exemplos posteriores em Crönert, p. 114; Hv 3, 1, 9; Reinhold, pp. 39s.). B-D-F §30, 3; 35, 3; W-S. §5, 20c; Mlt-H., pp. 67s., 329s.; Rob., índice.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Funciona como preposição com genitivo para indicar causa ou razão de alguma coisa: por causa de, em razão de, por amor de</strong>, Mt 5:10s.; 10:18, 39; 16:25; 19:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:35</a>; 10:29; 13:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:22</a>; 9:24; 18:29; 21:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:36</a> (Sl 43:23); 14:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:10</a>; 7:12; 2Cl 1:2; ITr 12:2; IPol 3:1; Pol 2:3; MPol 13:2; 17:3; Hv 1, 1, 6; 3, 1, 9; 3, 5, 2; m 5, 2, 2; 12, 4, 2; Hs 1:5; 9, 28, 5s.; D 10:3; B 14:9.</p><p class=\"entry-text\"><span class=\"greek\">ἕ</span>. <span class=\"greek\">τούτου</span>, «por essa razão» (Luciano, D. Deor. 23, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:7</a> (Gn 2:24); Hv 1, 3, 1; também <span class=\"greek\">ἕ</span>. <span class=\"greek\">τούτων</span>, «por essas coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:21</a> (PsSol 2:4). Com relativo <span class=\"greek\">οὗ</span> <span class=\"greek\">εἵ</span>., «em razão do qual» (Musônio, Ep. 1, 11; Quinto de Esmirna 12, 227; PGiss 27 [117 d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:18</a> (Is 61:1); <span class=\"greek\">τίνος</span> <span class=\"greek\">ἕ</span>.; «por quê?» (Demóstenes; Menandro, Epitr. 547 S. [371 Kö.]; Dio Crisóstomo 14 [31], 84; Taciano 9, 3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:32</a>; <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> com infinitivo subsequente (Menandro, Fgm. 358, 2 Kö.; Am 1:6; 2:4; 1Esd 8:21; Josefo, Ant. 11, 293).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Marcador de objetivo ou propósito: a fim de que</strong>; <span class=\"greek\">ἕ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">φανερωθῆναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σπουδὴν</span> <span class=\"greek\">ὑμῶν</span>, «a fim de que o vosso zelo se tornasse conhecido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 7:12</a> (B-D-F §403; Rob., p. 1073). — DELG; M-M.</p></section></article>\n<article id=\"entry-enekrypsa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέκρυψα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enékrypsa⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐγκρύπτω</span></strong>.</p></section></article>\n<article id=\"entry-enelisso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνελίσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enelíssō⟧</span><span class=\"separator\">·</span><span>verbo; forma conjectural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Perfeito passivo <span class=\"greek\">ἐνείλιγμαι</span> (ver <span class=\"greek\">ἐνειλέω</span>; Heródoto e outros). <strong>Envolver, enrolar</strong>, com dativo <span class=\"greek\">τινί</span>, «em alguma coisa» (POxy 1153, 23 [século I d.C.]); em nossa literatura ocorre somente como conjectura de Zahn: <span class=\"greek\">ἐνειλιγμένος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεσμοῖς</span>, «preso em correntes», Pol 1:1.</p></section></article>\n<article id=\"entry-enemeina-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέμεινα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enémeina⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐμμένω</span></strong>.</p></section></article>\n<article id=\"entry-enenekonta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνενήκοντα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enenḗkonta⟧</span><span class=\"separator\">·</span><span>numeral indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Indeclinável (Homero e outros; papiros, LXX; TestAbr A 1, p. 77, 2 [Stone, p. 2]; ApcSed 12:4; Fílon; Josefo, Ant. 18, 365; Taciano 31, 3, variante textual; sobre a grafia, ver B-D-F §11, 2; Mayser, p. 214). <strong>Noventa</strong>, Mt 18:12s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:4</a>, 7. — M-M.</p></section></article>\n<article id=\"entry-eneos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνεός, ά, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eneós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐννεός</span> no texto recebido (<em>textus receptus</em>); Platão e outros; LXX; Josefo, Ant. 4, 276. Sentido primário: <strong>relativo à incapacidade de falar: mudo</strong>; por extensão, <strong>sem fala, sem palavras</strong> (EpJer 40: <span class=\"greek\">ἐνεὸν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δυνάμενον</span> <span class=\"greek\">λαλῆσαι</span>, «mudo, incapaz de falar»). <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">εἱστήκεισαν</span> <span class=\"greek\">ἐνεοί</span>, «os homens ficaram sem palavras, tomados de medo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:7</a> (cf. Apolônio, Paradox. 6: Pitágoras <span class=\"greek\">ἤκουσε</span> <span class=\"greek\">φωνὴν</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἄνθρωπον</span> «<span class=\"greek\">Πυθαγόρα</span> <span class=\"greek\">χαῖρε</span>», «ouviu uma voz sobre-humana: 'Salve, Pitágoras!'», enquanto os presentes ficaram aterrorizados; Quinto de Esmirna 8, 250s.: os troianos <span class=\"greek\">ἐθάμβεον</span>, «ficaram pasmos», quando ouviram Ares ordenar-lhes algo, mas não conseguiram ver a forma do deus). — DELG; M-M.</p></section></article>\n<article id=\"entry-enepaixa-enepaichthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέπαιξα, ἐνεπαίχθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enépaixa, enepaíchthēn⟧</span><span class=\"separator\">·</span><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐμπαίζω</span></strong>.</p></section></article>\n<article id=\"entry-enepeson-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέπεσον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enepéson⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐμπίπτω</span></strong>.</p></section></article>\n<article id=\"entry-eneplesa-eneplesthen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέπλησα, ἐνεπλήσθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enéplēsa, eneplḗsthēn⟧</span><span class=\"separator\">·</span><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐμπίμπλημι</span></strong>.</p></section></article>\n<article id=\"entry-eneprese-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέπρησε</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enéprēse⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <strong><span class=\"greek\">ἐμπίμπρημι</span></strong>.</p></section></article>\n<article id=\"entry-energeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνέργεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦enérgeia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἐνεργής</span> e <span class=\"greek\">ἐνεργέω</span>; pré-socráticos e outros; inscrições, papiros, LXX; TestSol; EpArist; Fílon; Justino; Atenágoras; Hipólito. <strong>Estado ou qualidade de estar ativo: atividade, funcionamento, operação, ação.</strong> Assim no Novo Testamento, e sempre referente a seres transcendentes (cf. Crisipo, Stoic. II, p. 115; Diodoro Sículo 15, 48, 1: <span class=\"greek\">θεία</span> <span class=\"greek\">ἐ</span>., «atividade divina»; semelhantemente Orígenes, C. Cels. 3, 14, 7; Ps.-Calístenes 1, 30, 4: <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐ</span>., «a operação de Deus»; Salústio 3, p. 4, 8; 4, p. 4, 27; OGI 262, 4 [século III d.C.]: <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐνεργείας</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Διός</span>; Herm. Wr. 10, 22b; 16, 13: <span class=\"greek\">δαίμονος</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὐσία</span> <span class=\"greek\">ἐνέργεια</span>, «pois a essência de um espírito é atividade»; PGM 3, 290; Wsd 7:26; 13:4; 2Mc 3:29; 3Mc 4:21; 5:12, 28; EpArist 266; Aristóbulo em Eusébio, PE 8, 10, 12 [p. 142 Holladay]: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Dídimo, Gen. 247, 11: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">ἐνεργείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">οὐσίας</span> <span class=\"greek\">ἐστίν</span>, «o nome anjo designa atividade, e não essência»).</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐ</span>. <span class=\"greek\">πλάνης</span>, «influência que induz ao erro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:11</a>; <span class=\"greek\">πίστις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐνεργείας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «fé no poder (produtivo) de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:24</a>, códice D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:10</a>, variante textual.</p>\n<p class=\"entry-text\">Na maioria das ocorrências, na expressão <strong><span class=\"greek\">κατὰ</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">ἐνέργειαν</span></strong>, «segundo a atividade, operação»: <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κράτους</span>, «segundo a manifestação de seu poder», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:19</a> (para a construção genitiva, cf. 1QS 11, 19s.; 1QH 4, 32); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:7</a>; 4:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:29</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δύνασθαι</span> <span class=\"greek\">αὐτόν</span>, «mediante o poder que o capacita», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:21</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σατανᾶ</span>, «pela atividade de Satanás», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:9</a>. — <span class=\"greek\">ἐνεργείᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πονηροῦ</span>, «por instigação do maligno», AcPl Ha 9, 19 (cf. <span class=\"greek\">ὄφεως</span>, «da serpente», Justino, D. 39, 6; <span class=\"greek\">αἱ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δαιμόνων</span> <span class=\"greek\">ἐ</span>., «as atividades dos demônios», Orígenes, C. Cels. 1, 60, 6).</p>\n<p class=\"entry-text\">Referindo-se ao <strong>modo de operação: maneira de funcionar</strong>, <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀξυχολίας</span>, «da irritabilidade», Hm 5, 1, 7; 5, 2, 1. Com <span class=\"greek\">δύναμις</span>, «poder» (Aristóteles, p. 23a, 10ss.; Fílon, Rer. Div. Her. 110 e outros; Atenágoras 10, 3; 26, 1), Hm 6, 1, 1a. No plural (Epicteto 2, 16, 18; 4, 11, 33; Fílon; Atenágoras), Hm 6, 1, 1b; 6, 2, 2 e 6. O plural também em v 3, 8, 3, onde o termo se refere àquilo que alguma coisa está equipada para fazer e pode ser traduzido por <strong>função</strong>. — DELG, s.v. <span class=\"greek\">ἔργον</span>; RAC V, pp. 4–51; M-M.; TW.</p></section></article>\n<article id=\"entry-energeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐνεργέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦energéō⟧</span><span class=\"separator\">·</span><span>verbo; transitivo e intransitivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐνήργησα</span>; perfeito <span class=\"greek\">ἐνήργηκα</span>; infinitivo aoristo passivo <span class=\"greek\">ἐνεργηθῆναι</span>; particípio aoristo passivo <span class=\"greek\">ἐνεργηθέντα</span> (ver <span class=\"greek\">ἐνέργεια</span>; Justino, D. 78, 6; A I, 26, 4). Desde Aristóteles.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> <strong>Intransitivo: pôr as próprias capacidades em funcionamento, trabalhar, estar em atividade, atuar, operar, ser eficaz.</strong></p>\n<p class=\"entry-text\">ⓐ <strong>Na voz ativa</strong> (Fílon de Bizâncio, Mech. 59, 48; 96, 12; Vettius Valens 226, 2; Herm. Wr. 12, 11ab; PGiss 78, 4 [século II d.C.]: <span class=\"greek\">καλῶς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ποιήσεις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">ἐνεργήσασα</span>; Sb 15:11; 16:17; Josefo, Ant. 15, 290; Vi. 156). <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐ</span>., «o querer e o agir», Fp 2:13b. Com <span class=\"greek\">ἐν</span> e dativo de pessoa (TestDan 5:5: <span class=\"greek\">ἐνεργούντων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span>; TestSim 4:8; sem <span class=\"greek\">ἐν</span>, Atenágoras 10, 3), <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">ἐνεργοῦσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, «os poderes milagrosos estão atuando nele», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:2</a>. Referindo-se a Deus (Juliano 4, 142d: <span class=\"greek\">ἐνεργεῖν</span> <span class=\"greek\">ἐθέλει</span>), <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐνεργῶν</span>, «aquele que atua», B 2:1 (ver H. Windisch, Hdb., ad loc.). Com dativo de benefício (cf. Pv 31:12), <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐνεργήσας</span> <span class=\"greek\">Πέτρῳ</span>, «aquele que atuou em favor de Pedro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:8</a> (o <span class=\"greek\">εἰς</span> subsequente indica o objetivo da atividade, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:5</a>; ver b abaixo).</p>\n<p class=\"entry-text\">ⓑ <strong>Na voz média</strong>, em nossa literatura sempre com sujeito impessoal (Diodoro Sículo 13, 85, 2: o cerco «entrou em vigor», «começou»; Herm. Wr. 12, 11c: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀσώματα</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">παθήματα</span> <span class=\"greek\">ἐνηργεῖτο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μέλεσιν</span>, «as paixões estavam atuando em nossos membros», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:5</a> (o <span class=\"greek\">εἰς</span> subsequente introduz o objetivo; ver a acima, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:8</a>). <span class=\"greek\">ἡ</span> <span class=\"greek\">παράκλησις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐνεργουμένη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑπομονῇ</span>, «a consolação que atua no ato de perseverar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:6</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θάνατος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἐνεργεῖται</span>, «a morte está atuando em nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:12</a> (Luciano, Charon 2: <span class=\"greek\">ἐνεργεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">ἔργα</span>, «realizar as obras da morte»). Da palavra de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:13</a>. <span class=\"greek\">δύναμις</span> <span class=\"greek\">ἐνεργουμένη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span>, «o poder que atua em nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 3:20</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:29</a>. <span class=\"greek\">πίστις</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">ἐνεργουμένη</span>, «fé que atua (= se expressa) por meio do amor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:6</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">ἐνεργεῖται</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span>, «a força secreta da iniquidade está atuando = está em operação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:7</a>. <span class=\"greek\">δέησις</span> <span class=\"greek\">ἐνεργουμένη</span>, «oração eficaz», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:16</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνεργούμενα</span>, «as forças em atividade», 1Cl 60:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἕκαστα</span> <span class=\"greek\">βλέποντες</span> <span class=\"greek\">ἐνεργούμενα</span>, «vemos como cada coisa, uma após outra, produz seus efeitos = acontece», B 1:7. — J. Ross, «<span class=\"greek\">ἐνεργεῖσθαι</span> in the NT», Exp., sétima série, 7, 1909, pp. 75–77; J. Mayor, ibid., pp. 191s.; A. Garvie, ET 55, 1943/44, p. 97. Para a interpretação segundo a qual as passagens de b são passivas, e não médias, ver o artigo de Clark citado adiante, pp. 98ss., e suas referências.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> <strong>Transitivo: fazer que alguma coisa aconteça mediante o emprego de uma capacidade: realizar, produzir, efetuar</strong>, com acusativo (de pessoa em Justino, A I, 26, 4; Atenágoras 9, 1 e outros; de coisa em Fílon de Bizâncio, Mech. 59, 48; Políbio 3, 6, 5; Diodoro Sículo 13, 85, 2; POxy 1567; Pv 21:6; 31:12; Josefo, Ant. 3, 155; 15, 283; Justino, A I, 12, 5: <span class=\"greek\">ταῦτα</span>; 23, 3: <span class=\"greek\">ἀσεβῆ</span> <span class=\"greek\">ἔργα</span> e outros; Irineu 3, 21, 2 [Harv. II 114, 6]; <span class=\"greek\">δαίμονες</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">λοιμούς</span>, «demônios provocam epidemias», Orígenes, C. Cels. 1, 31, 27; <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">δύναμίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἐνεργοῦσα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιστροπφήν</span>, «o poder de Jesus produz a conversão», 1, 43, 39; Hipólito).</p>\n<p class=\"entry-text\">Com acusativo <span class=\"greek\">τί</span>, «alguma coisa»: de Deus, <span class=\"greek\">ὁ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐνεργῶν</span>, «aquele que realiza todas as coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:11</a> (cf. EpArist 210); do Espírito, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:2</a>. Com <span class=\"greek\">τί</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «produzir alguma coisa em alguém»: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐνεργῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, «aquele que produz todas as coisas em todos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12:6</a>; cf. v. 11; <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐνεργῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλειν</span>, «aquele que produz em vós o querer», Fp 2:13a. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐνεργῆσαι</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτούς</span>, «nem sequer pode influenciá-los», Hm 5, 2, 1 (cf. Justino, D. 18, 3: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀνθρώπων</span> … <span class=\"greek\">ἐνεργούμενα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμᾶς</span>); <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">ἐ</span>., «operar milagres», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:5</a> (Justino, D. 7, 3); <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">ἐ</span>., «realizar uma ação», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:20</a>. Com acusativo e infinitivo: Justino, A I, 62, 1 e outros. — G. Whitaker, ET 26, 1914/15, pp. 474–476; K. Clark, «The Meaning of <span class=\"greek\">ἐνεργέω</span> and <span class=\"greek\">καταργέω</span> in the NT», JBL 54, 1935, pp. 93–101; M-M.; TW.</p></section></article>"};
